// Match do GBP pelo TELEFONE (últimos 8 dígitos) — nome de MEI raramente bate
const lead = $('Buscar Leads Validados').item.json;
const places = ($json.places || []);

const dig = s => String(s || '').replace(/\D/g, '');
const fim8 = s => dig(s).slice(-8);

const candidatos = new Set();
if (lead.whatsapp) candidatos.add(fim8(lead.whatsapp));
for (const t of (lead.telefones_json || [])) {
  if (t && t.number) candidatos.add(fim8(`${t.area || ''}${t.number}`));
}

let gbp = null;
let confianca = null;
for (const p of places) {
  const fones = [p.nationalPhoneNumber, p.internationalPhoneNumber].map(fim8).filter(Boolean);
  if (fones.some(f => candidatos.has(f))) { gbp = p; confianca = 'telefone'; break; }
}
if (!gbp) {
  // Fallback por nome+cidade com validação de assertividade:
  // match fraco é pior que nenhum match (nunca citar o negócio errado na msg1).
  const norm = s => String(s || '')
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, ''); // remove acentos
  const STOPWORDS = new Set(['de','da','do','das','dos','e','ltda','me','mei','eireli','epp','studio','espaco','clinica','estetica','salao','dra','dr']);
  const palavrasLead = norm(lead.nome_exibicao).split(/\s+/).filter(w => w.length >= 3 && !STOPWORDS.has(w));
  const bairroLead = norm(lead.bairro);

  const candidatosNome = places.filter(p => {
    const endereco = norm(p.formattedAddress);
    const nomePlace = norm(p.displayName?.text);
    const mesmaCidade = endereco.includes(norm(lead.municipio));
    if (!mesmaCidade || !palavrasLead.length) return false;
    const palavrasBatendo = palavrasLead.filter(w => nomePlace.includes(w)).length;
    const bairroBate = bairroLead.length >= 4 && endereco.includes(bairroLead);
    // Aceita se: nome bate forte (2+ palavras significativas)
    // OU nome bate 1 palavra E o bairro do CNPJ confere no endereço do place
    return palavrasBatendo >= 2 || (palavrasBatendo >= 1 && bairroBate);
  });

  if (candidatosNome.length) {
    // Entre os candidatos válidos, escolhe o mais "completo" em dados —
    // perfis duplicados/incompletos do mesmo negócio não devem vencer.
    const completude = p => {
      let pontos = 0;
      if (p.nationalPhoneNumber || p.internationalPhoneNumber) pontos += 2;
      if (typeof p.userRatingCount === 'number' && p.userRatingCount > 0) pontos += 2;
      if (typeof p.rating === 'number') pontos += 1;
      if (Array.isArray(p.photos) && p.photos.length) pontos += 1;
      if (p.regularOpeningHours?.periods?.length) pontos += 1;
      return pontos;
    };
    gbp = candidatosNome.reduce((melhor, atual) =>
      completude(atual) > completude(melhor) ? atual : melhor
    );
    confianca = 'nome_endereco';
  }
}

// Até 5 reviews (subiu de 3), com data para permitir calcular recência.
// publishTime vem em ISO 8601 (RFC3339) direto da Places API.
const reviews = (gbp?.reviews || []).slice(0, 5).map(r => ({
  texto: String(r.text?.text || '').slice(0, 250),
  nota: r.rating,
  autor: r.authorAttribution?.displayName || null,
  publicado_em: r.publishTime || null
}));

// Review mais recente => sinal de quão "vivo" está o GBP
let reviewMaisRecenteDias = null;
const datas = reviews.map(r => r.publicado_em).filter(Boolean).map(d => new Date(d).getTime()).filter(t => !isNaN(t));
if (datas.length) {
  const maisRecente = Math.max(...datas);
  reviewMaisRecenteDias = Math.floor((Date.now() - maisRecente) / 86400000);
}

// Sinais extras do GBP — mesmo tier de custo do FieldMask, já incluídos na resposta
const fotosQtd = Array.isArray(gbp?.photos) ? gbp.photos.length : 0;
const temHorario = !!(gbp?.regularOpeningHours && Array.isArray(gbp.regularOpeningHours.periods) && gbp.regularOpeningHours.periods.length > 0);
const tipoGoogle = gbp?.primaryTypeDisplayName?.text || null;
const editorial = gbp?.editorialSummary?.text ? String(gbp.editorialSummary.text).slice(0, 300) : null;

return { json: {
  lead,
  tem_gbp: !!gbp,
  gbp: gbp ? {
    gbp_place_id: gbp.id,
    gbp_business_status: gbp.businessStatus ?? null,
    gbp_rating: gbp.rating ?? null,
    gbp_avaliacoes: gbp.userRatingCount ?? null,
    gbp_url: gbp.googleMapsUri || null,
    gbp_reviews: reviews,
    gbp_match_confianca: confianca
  } : null,
  gbp_extra: gbp ? {
    gbp_fotos_qtd: fotosQtd,
    gbp_tem_horario: temHorario,
    gbp_tipo_google: tipoGoogle,
    gbp_editorial: editorial,
    review_mais_recente_dias: reviewMaisRecenteDias
  } : null,
  site_url: gbp?.websiteUri || null
} };

// Pré-diagnóstico do site e preparação do pedido de análise
const base = $('Match GBP').item.json;
const lead = base.lead;
const siteUrl = base.site_url;

const TERCEIROS = /instagram\.com|facebook\.com|linktr\.ee|wa\.me|api\.whatsapp|doctoralia|ifood|tripadvisor|google\.com/i;

let site_status = null;
let html_trecho = null;
let htmlBruto = null;

if (!siteUrl) {
  site_status = 'sem_site';
} else if (TERCEIROS.test(siteUrl)) {
  site_status = 'terceiros';
} else if ($json.error || typeof $json.html !== 'string') {
  site_status = 'fora_do_ar';
} else {
  site_status = 'ok_analisar';
  htmlBruto = String($json.html);
  html_trecho = htmlBruto
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/\s+/g, ' ')
    .slice(0, 12000);
}

const idade_dias = lead.data_abertura ? Math.floor((Date.now() - new Date(lead.data_abertura).getTime()) / 86400000) : null;

// --- Extração determinística via regex sobre o HTML bruto (custo zero) ---
let instagram_handle = null;
let site_titulo = null;
let site_meta_description = null;
let site_tem_whatsapp = false;
const site_https = /^https:\/\//i.test(siteUrl || '');

if (htmlBruto) {
  // Instagram: pega o handle e descarta paths que não são perfil
  const EXCLUIR_IG = new Set(['p', 'reel', 'reels', 'explore', 'accounts', 'sharer', 'stories', 'tv']);
  const igMatches = [...htmlBruto.matchAll(/instagram\.com\/([a-zA-Z0-9._]+)/gi)];
  for (const m of igMatches) {
    const handle = m[1].replace(/\.$/, '');
    if (handle && !EXCLUIR_IG.has(handle.toLowerCase())) { instagram_handle = handle; break; }
  }

  // Título
  const tituloMatch = htmlBruto.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (tituloMatch) {
    site_titulo = tituloMatch[1].replace(/\s+/g, ' ').trim().slice(0, 150) || null;
  }

  // Meta description (fallback para og:description)
  const metaDescMatch = htmlBruto.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i)
    || htmlBruto.match(/<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i);
  const ogDescMatch = htmlBruto.match(/<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i)
    || htmlBruto.match(/<meta[^>]+content=["']([^"']*)["'][^>]+property=["']og:description["']/i);
  const descBruta = (metaDescMatch && metaDescMatch[1]) || (ogDescMatch && ogDescMatch[1]) || null;
  if (descBruta) site_meta_description = descBruta.replace(/\s+/g, ' ').trim().slice(0, 300) || null;

  // Botão/link de WhatsApp no site
  site_tem_whatsapp = /wa\.me\/|api\.whatsapp\.com/i.test(htmlBruto);
}

return { json: {
  lead, tem_gbp: base.tem_gbp, gbp: base.gbp, gbp_extra: base.gbp_extra, site_url: siteUrl,
  site_status_previo: site_status, html_trecho, idade_dias,
  site_extra: {
    instagram_handle,
    site_titulo,
    site_meta_description,
    site_tem_whatsapp,
    site_https
  }
} };

// Interpreta a resposta do Claude e monta o PATCH final da empresa
const prep = $('Preparar Análise').item.json;
const lead = prep.lead;
let c = null;
try {
  const texto = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  c = JSON.parse(texto.replace(/```json|```/g, '').trim());
} catch (e) { c = null; }
const agora = new Date().toISOString();
const patch = {
  tem_gbp: prep.tem_gbp,
  tem_site: prep.site_status_previo === 'ok_analisar' || prep.site_status_previo === 'fora_do_ar',
  site_url: prep.site_url,
  enriquecido_em: agora
};
if (prep.gbp) Object.assign(patch, prep.gbp);

// enriquecimento_extra: parte determinística (sempre grava, mesmo se o Claude falhar)
const enriquecimentoExtra = {
  ...(prep.site_extra || {}),
  ...(prep.gbp_extra || {}),
  review_destaque: null
};

if (c) {
  patch.site_status = c.site_status || prep.site_status_previo;
  patch.site_sinais = c.site_sinais || [];
  patch.site_diagnostico = c.site_diagnostico || null;
  //patch.score = typeof c.score === 'number' ? c.score : null;
  // Trava de segurança: recalcula o perfil pela regra determinística,
  // não confia cegamente no que o Claude decidiu
  const temGbp = !!prep.tem_gbp;
  const siteRuim = ['fraco', 'fora_do_ar', 'terceiros'].includes(patch.site_status);
  const temSite = patch.site_status === 'ok' || siteRuim;
  let perfil;
  if (prep.idade_dias !== null && prep.idade_dias < 90) perfil = 'recem_aberta';
  else if (temGbp && siteRuim) perfil = 'redesign';
  else if (temGbp && !temSite) perfil = 'site_para_gbp';
  else if (!temGbp && temSite) perfil = 'sem_gbp';
  else if (!temGbp && !temSite) perfil = 'criacao_zero';
  else perfil = (temGbp && patch.site_status === 'ok') ? 'descartado_site_bom' : (c.perfil_oferta || 'criacao_zero');
  patch.perfil_oferta = perfil;
  patch.dor_resumida = c.dor_resumida || null;
  patch.status = perfil.startsWith('descartado') ? 'descartado' : 'fila';
  if (perfil.startsWith('descartado')) patch.motivo_descarte = 'site_bom';

  // review_destaque só entra se vier casado com um GBP de fato (evita citar
  // review de outro negócio caso o Claude confunda dados)
  if (prep.tem_gbp && c.review_destaque && c.review_destaque.texto) {
    enriquecimentoExtra.review_destaque = {
      texto: String(c.review_destaque.texto).slice(0, 150),
      nota: c.review_destaque.nota ?? null,
      autor: c.review_destaque.autor || null
    };
  }

  // TRAVA DETERMINÍSTICA DO GANCHO (o prompt sozinho não garante):
  // gancho só é aceito se existir pelo menos UMA fonte real e verificável:
  //   (a) rating >= 4.5 com pelo menos 1 avaliação
  //   (b) review_destaque válido (já validado acima)
  //   (c) editorial do Google presente
  // Sem fonte => null, independente do que o Claude tiver escrito.
  const rating = prep.gbp?.gbp_rating;
  const avaliacoes = prep.gbp?.gbp_avaliacoes;
  const temFonteRating = typeof rating === 'number' && rating >= 4.5
    && typeof avaliacoes === 'number' && avaliacoes > 0;
  const temFonteReview = !!enriquecimentoExtra.review_destaque;
  const temFonteEditorial = !!(prep.gbp_extra && prep.gbp_extra.gbp_editorial);
  const ganchoPermitido = temFonteRating || temFonteReview || temFonteEditorial;
  patch.gancho_abordagem = (ganchoPermitido && c.gancho_abordagem) ? c.gancho_abordagem : null;
} else {
  patch.site_status = prep.site_status_previo === 'ok_analisar' ? null : prep.site_status_previo;
  patch.enriquecido_em = null;
  patch.gancho_abordagem = null;
  patch.obs = ((lead.obs || '') + ' | Classificação falhou em ' + agora).trim();
}

patch.enriquecimento_extra = enriquecimentoExtra;

// patch-09: Google marca o negócio como fechado permanentemente → descarta sempre
if (patch.gbp_business_status === 'CLOSED_PERMANENTLY') {
  patch.status = 'descartado';
  patch.motivo_descarte = 'fechada_google';
}
return { json: { id: lead.id, slug: lead.slug, patch, perfil: patch.perfil_oferta || 'falha' } };

// Resumo por perfil de oferta
const itens = $('Aplicar Classificação').all().map(i => i.json);
const porPerfil = {};
for (const i of itens) porPerfil[i.perfil] = (porPerfil[i.perfil] || 0) + 1;
return [{ json: { processados: itens.length, por_perfil: porPerfil } }];

// Roda UMA vez para o lote inteiro: reconstrói os itens a partir do
// "Aplicar Classificação" e cruza com os donos de place retornados
// pela consulta batelada do "Checar Place Duplicado".
// Garantia estrutural: N itens entram na origem => N itens saem daqui.
const classif = $('Aplicar Classificação').all().map(i => i.json);

let donos = [];
try {
  donos = $input.all().map(i => i.json).filter(j => j && j.id !== undefined);
} catch (e) { donos = []; }

const out = [];
for (const item of classif) {
  const patch = { ...item.patch };

  const conflito = patch.gbp_place_id && donos.some(d =>
    d.gbp_place_id === patch.gbp_place_id && d.id !== item.id
  );

  if (conflito) {
    // Remove o vínculo de GBP para não colidir com outra empresa já dona desse place
    delete patch.gbp_place_id;
    delete patch.gbp_business_status;
    delete patch.gbp_rating;
    delete patch.gbp_avaliacoes;
    delete patch.gbp_url;
    delete patch.gbp_reviews;
    delete patch.gbp_match_confianca;
    patch.tem_gbp = false;
    patch.obs = ((item.patch.obs || '') + ' | gbp_place_id conflitante removido (' + new Date().toISOString() + ')').trim();

    // Limpa também os dados do GBP dentro de enriquecimento_extra
    if (patch.enriquecimento_extra) {
      const extra = { ...patch.enriquecimento_extra };
      delete extra.gbp_fotos_qtd;
      delete extra.gbp_tem_horario;
      delete extra.gbp_tipo_google;
      delete extra.gbp_editorial;
      delete extra.review_mais_recente_dias;
      extra.review_destaque = null;
      patch.enriquecimento_extra = extra;
    }

    // gancho pode ter sido construído em cima do GBP conflitante
    patch.gancho_abordagem = null;

    // Recalcula perfil_oferta considerando que agora tem_gbp = false
    const siteRuim = ['fraco', 'fora_do_ar', 'terceiros'].includes(patch.site_status);
    const temSite = patch.site_status === 'ok' || siteRuim;
    if (patch.perfil_oferta !== 'recem_aberta') {
      patch.perfil_oferta = temSite ? 'sem_gbp' : 'criacao_zero';
      patch.status = 'fila';
    }
  }

  out.push({ json: { id: item.id, slug: item.slug, patch, perfil: patch.perfil_oferta } });
}

return out;
